// Embedded Web UI
const INDEX_HTML: &str = r##"<!DOCTYPE html>
<html lang=\"zh-CN\"><head>
<meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">
<title>Nexa · Rust</title>
<link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.svg\">
<link rel=\"stylesheet\" href=\"/style.css\">
</head><body><div id=\"app\"></div><script src=\"/app.js\"></script></body></html>
"##;

const FAVICON_SVG: &str = r##"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\"><rect width=\"32\" height=\"32\" rx=\"6\" fill=\"#0f172a\"/><text x=\"16\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" fill=\"#38bdf8\">N</text></svg>"##;

const STYLE_CSS: &str = r##"
:root{--bg:#0b1220;--surface:#111827;--surface2:#1a2332;--border:#1e293b;--text:#e2e8f0;--muted:#94a3b8;--accent:#38bdf8;--success:#34d399;--danger:#f87171}
*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh}
button{cursor:pointer;border:none;border-radius:8px;padding:8px 16px;font-size:14px;background:var(--accent);color:#0b1220}
button.secondary{background:var(--surface2);color:var(--text);border:1px solid var(--border)}
button.danger{background:var(--danger);color:#fff}button.success{background:var(--success);color:#0b1220}
input,select,textarea{background:var(--surface2);border:1px solid var(--border);border-radius:8px;color:var(--text);padding:8px 12px;width:100%}
.layout{display:flex;min-height:100vh}.sidebar{width:200px;background:var(--surface);border-right:1px solid var(--border);padding:16px 10px}
.logo{font-size:18px;font-weight:700;color:var(--accent);padding:8px 10px 16px}
.nav-item{display:block;padding:9px 10px;border-radius:8px;color:var(--muted);cursor:pointer;font-size:14px}
.nav-item.active,.nav-item:hover{background:var(--surface2);color:var(--text)}
.main{flex:1;padding:24px}.page-title{font-size:20px;font-weight:600;margin-bottom:16px}
.card{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:16px;margin-bottom:12px}
.login-wrap{min-height:100vh;display:flex;align-items:center;justify-content:center}
.login-card{width:340px;background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:32px}
.toast{position:fixed;bottom:20px;right:20px;background:var(--surface2);border:1px solid var(--border);padding:10px 16px;border-radius:8px;z-index:9999}
.status-badge{display:inline-block;padding:3px 10px;border-radius:999px;font-size:13px}
.status-badge.running{background:rgba(52,211,153,.15);color:var(--success)}
.status-badge.stopped{background:rgba(248,113,113,.15);color:var(--danger)}
.log-box{background:#0a0f1a;border:1px solid var(--border);border-radius:8px;padding:10px;font-family:monospace;font-size:12px;max-height:400px;overflow:auto;white-space:pre-wrap;color:#a5b4fc}
table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--border)}
.field{margin-bottom:12px}label{display:block;font-size:12px;color:var(--muted);margin-bottom:3px}
.actions{display:flex;gap:8px;flex-wrap:wrap}
"##;

const APP_JS: &str = r##"
'use strict';
const API=(()=>{const t=()=>localStorage.getItem('nexa_token');async function r(p,o={}){o.headers=o.headers||{};if(t())o.headers.Authorization='Bearer '+t();if(o.body&&typeof o.body!=='string'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(o.body)}const res=await fetch(p,o);if(res.status===401){location.hash='#/login';throw new Error('未授权')}const ct=res.headers.get('Content-Type')||'';return ct.includes('json')?res.json():res.text()}return{get:p=>r(p),post:(p,b)=>r(p,{method:'POST',body:b}),put:(p,b)=>r(p,{method:'PUT',body:b}),del:p=>r(p,{method:'DELETE'})}})();
const UI={toast(m){const e=document.createElement('div');e.className='toast';e.textContent=m;document.body.appendChild(e);setTimeout(()=>e.remove(),2800)},el(tag,a={},...ch){const e=document.createElement(tag);for(const k in a){if(k==='class')e.className=a[k];else if(k==='html')e.innerHTML=a[k];else if(k.startsWith('on'))e.addEventListener(k.slice(2).toLowerCase(),a[k]);else if(a[k]!=null)e.setAttribute(k,a[k])}for(const c of ch){if(c!=null)e.appendChild(typeof c==='string'?document.createTextNode(c):c)}return e}};
function pageLogin(){const w=UI.el('div',{class:'login-wrap'});const c=UI.el('div',{class:'login-card'});const u=UI.el('input',{value:'admin'});const p=UI.el('input',{type:'password'});const b=UI.el('button',{},'登录');b.onclick=async()=>{try{const r=await API.post('/api/auth/login',{username:u.value,password:p.value});localStorage.setItem('nexa_token',r.token);location.hash='#/';UI.toast('登录成功')}catch(e){UI.toast(e.message)}};c.append(UI.el('h1',{},'Nexa'),UI.el('p',{style:'color:var(--muted);margin:8px 0 16px'},'Rust 透明代理面板'),UI.el('div',{class:'field'},UI.el('label',{},'用户名'),u),UI.el('div',{class:'field'},UI.el('label',{},'密码'),p),b);w.append(c);return w}
function layout(act,content){const nav=[['','概览'],['config','配置'],['proxy','代理'],['routing','路由'],['profiles','配置文件'],['logs','日志'],['debug','调试'],['settings','设置']];const s=UI.el('div',{class:'sidebar'});s.append(UI.el('div',{class:'logo',html:'Nexa'}));nav.forEach(([id,l])=>{s.append(UI.el('div',{class:'nav-item'+(act===id?' active':''),onClick:()=>{location.hash='#/'+id}},l))});return UI.el('div',{class:'layout'},s,UI.el('div',{class:'main'},content))}
async function pageDashboard(){let st={};try{st=await API.get('/api/status')}catch(_){}const run=st.core&&st.core.running;return layout('',UI.el('div',{},UI.el('div',{class:'page-title'},'概览'),UI.el('div',{class:'card'},UI.el('span',{class:'status-badge '+(run?'running':'stopped')},run?'运行中':'已停止'),UI.el('div',{class:'actions',style:'margin-top:12px'},UI.el('button',{class:'success',onClick:async()=>{await API.post('/api/start');render()}},'启动'),UI.el('button',{class:'danger',onClick:async()=>{await API.post('/api/stop');render()}},'停止'),UI.el('button',{class:'secondary',onClick:async()=>{await API.post('/api/restart');render()}},'重启'),UI.el('button',{class:'secondary',onClick:async()=>{const r=await API.post('/api/config/apply');UI.toast(r.message||'ok')}},'应用'),UI.el('button',{class:'secondary',onClick:async()=>{const r=await API.post('/api/net/on');UI.toast(r.message||'ok')}},'网络On'),UI.el('button',{class:'danger',onClick:async()=>{const r=await API.post('/api/net/off');UI.toast(r.message||'ok')}},'网络Off'))))}
async function pageConfig(){let cfg={config:{}};try{cfg=await API.get('/api/config')}catch(_){}const c=cfg.config||{};const en=UI.el('input',{type:'checkbox'});en.checked=!!c.enabled;const pf=UI.el('input',{value:c.profile||'config.yaml'});const bin=UI.el('input',{value:c.run_binary||'sing-box'});return layout('config',UI.el('div',{},UI.el('div',{class:'page-title'},'配置'),UI.el('div',{class:'card'},UI.el('div',{class:'field'},UI.el('label',{},'启用'),en),UI.el('div',{class:'field'},UI.el('label',{},'配置文件'),pf),UI.el('div',{class:'field'},UI.el('label',{},'二进制'),bin),UI.el('button',{onClick:async()=>{cfg.config={...c,enabled:en.checked,profile:pf.value,run_binary:bin.value};await API.put('/api/config',cfg);UI.toast('已保存')}},'保存'))))}
async function pageProxy(){let cfg={proxy:{}};try{cfg=await API.get('/api/config')}catch(_){}const p=cfg.proxy||{};const tcp=UI.el('select',{},UI.el('option',{value:'tproxy'},'tproxy'),UI.el('option',{value:'tun'},'tun'));tcp.value=p.tcp_mode||'tproxy';return layout('proxy',UI.el('div',{},UI.el('div',{class:'page-title'},'代理'),UI.el('div',{class:'card'},UI.el('div',{class:'field'},UI.el('label',{},'TCP'),tcp),UI.el('button',{onClick:async()=>{cfg.proxy={...p,tcp_mode:tcp.value};await API.put('/api/config',cfg);UI.toast('已保存')}},'保存'))))}
async function pageRouting(){let cfg={routing:{}};try{cfg=await API.get('/api/config')}catch(_){}const r=cfg.routing||{};const keys=[['tproxy_fw_mark','TProxy mark'],['tproxy_route_table','TProxy table'],['tun_fw_mark','TUN mark'],['tun_route_table','TUN table']];const fields={};const card=UI.el('div',{class:'card'});keys.forEach(([k,l])=>{const i=UI.el('input',{value:r[k]!=null?String(r[k]):''});fields[k]=i;card.append(UI.el('div',{class:'field'},UI.el('label',{},l),i))});card.append(UI.el('button',{onClick:async()=>{keys.forEach(([k])=>{r[k]=fields[k].value});cfg.routing=r;await API.put('/api/config',cfg);UI.toast('已保存')}},'保存'));return layout('routing',UI.el('div',{},UI.el('div',{class:'page-title'},'路由'),card))}
async function pageProfiles(){let list=[];try{list=(await API.get('/api/profiles')).profiles||[]}catch(_){}const ed=UI.el('textarea',{style:'min-height:160px;width:100%'});const ni=UI.el('input',{placeholder:'文件名'});const tb=UI.el('table');list.forEach(n=>{tb.append(UI.el('tr',{},UI.el('td',{},n),UI.el('td',{},UI.el('button',{class:'secondary',onClick:async()=>{ed.value=await API.get('/api/profiles/'+encodeURIComponent(n));ni.value=n}},'编辑'))))});return layout('profiles',UI.el('div',{},UI.el('div',{class:'page-title'},'配置文件'),UI.el('div',{class:'card'},tb),UI.el('div',{class:'card'},ni,ed,UI.el('button',{onClick:async()=>{const n=ni.value||'config.yaml';await API.put('/api/profiles/'+encodeURIComponent(n),{content:ed.value});UI.toast('已保存');render()}},'保存'))))}
async function pageLogs(){let a='',c='';try{a=await API.get('/api/logs/app')}catch(_){}try{c=await API.get('/api/logs/core')}catch(_){}return layout('logs',UI.el('div',{},UI.el('div',{class:'page-title'},'日志'),UI.el('div',{class:'card'},UI.el('div',{class:'log-box'},a||'(empty)')),UI.el('div',{class:'card'},UI.el('div',{class:'log-box'},c||'(empty)'))))}
async function pageDebug(){const out=UI.el('div',{class:'log-box'},'…');const run=async cmd=>{try{out.textContent=(await API.post('/api/debug',{cmd})).output}catch(e){out.textContent=e.message}};return layout('debug',UI.el('div',{},UI.el('div',{class:'page-title'},'调试'),UI.el('div',{class:'card'},UI.el('div',{class:'actions'},UI.el('button',{class:'secondary',onClick:()=>run('ip_rule')},'ip rule'),UI.el('button',{class:'secondary',onClick:()=>run('nft')},'nft'),UI.el('button',{class:'secondary',onClick:()=>run('ps')},'ps')),out)))}
async function pageSettings(){return layout('settings',UI.el('div',{},UI.el('div',{class:'page-title'},'设置'),UI.el('div',{class:'card'},UI.el('button',{class:'danger',onClick:()=>{localStorage.removeItem('nexa_token');location.hash='#/login'}},'退出'))))}
async function render(){const app=document.getElementById('app');const page=((location.hash||'#/').replace(/^#\/?/,'').split('?')[0]);if(page==='login'){app.innerHTML='';app.append(pageLogin());return}if(!localStorage.getItem('nexa_token')){try{const r=await fetch('/api/auth/no-auth');if(r.ok&&!(await r.json()).no_auth){location.hash='#/login';return}}catch(_){location.hash='#/login';return}}let c;try{if(!page)c=await pageDashboard();else if(page==='config')c=await pageConfig();else if(page==='proxy')c=await pageProxy();else if(page==='routing')c=await pageRouting();else if(page==='profiles')c=await pageProfiles();else if(page==='logs')c=await pageLogs();else if(page==='debug')c=await pageDebug();else if(page==='settings')c=await pageSettings();else c=await pageDashboard()}catch(e){c=UI.el('div',{},'错误: '+e.message)}app.innerHTML='';app.append(c)}
window.addEventListener('hashchange',render);render();
"##;
